use vstd::prelude::*;

verus! {
    // Given a vector of f64, produce a new vector of length one greater,
    // with 0.0 at the front and the rest shifted by one.
    fn hermemulx(c: Vec<f64>) -> (result: Vec<f64>)
        ensures
            // The result has exactly one more element than c
            result.len() == c.len() + 1,
            // First element is 0.0
            result[0] == 0.0,
            // For every valid index i in c, result[i+1] == c[i]
            forall|i: usize| i < c.len() ==> result[i + 1] == c[i],
    {
        // Start with an empty vector and push the 0.0 prefix
        let mut result: Vec<f64> = Vec::new();
        result.push(0.0);

        // idx is how many elements of c we've copied so far
        let mut idx: usize = 0;

        // Loop to push each element of c in order
        while idx < c.len()
            invariant
                // idx never exceeds c.len()
                idx <= c.len(),
                // We have pushed exactly idx elements from c,
                // plus the initial 0.0, so length is idx + 1
                result.len() == idx + 1,
                // The prefix at position 0 remains 0.0
                result[0] == 0.0,
                // For all j < idx, result[j+1] == c[j]
                forall|j: usize| j < idx ==> result[j + 1] == c[j],
            decreases
                // Terminates as idx increases
                c.len() - idx,
        {
            // Push the next element of c
            result.push(c[idx]);

            // Account for the push in idx
            idx = idx + 1;

            // Now length should be idx + 1 again
            assert(result.len() == idx + 1);
            // And the newly pushed element satisfies result[idx] == c[idx-1]
            assert(result[idx] == c[idx - 1]);
        }

        result
    }
}

